    /// Drawn once, then tinted like text by whatever colour surrounds it.
    var image: NSImage {
        if let cached = Self.cache[self] { return cached }
        let svg = #"<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" color="black">"# + shapes + "</svg>"
        let image = NSImage(data: Data(svg.utf8)) ?? NSImage()
        image.isTemplate = true
        Self.cache[self] = image
        return image
    }

    private static var cache: [Icon: NSImage] = [:]
}

extension Icon {
    /// Apple's SF Symbols name for this icon. The app draws every icon from
    /// SF Symbols, which Apple licenses for the interfaces of apps on its
    /// platforms; the Hugeicons drawings above are kept for the website.
    var symbol: String {
        switch self {
        case .arrowLeft: "chevron.left"
        case .arrowUp: "arrow.up"
        case .folder: "folder"
        case .image: "photo"
        case .settings: "gearshape"
        case .mail: "envelope"
        case .checklist: "checklist"
        case .timer: "timer"
        case .code: "chevron.left.forwardslash.chevron.right"
        case .computer: "desktopcomputer"
        case .activity: "waveform.path.ecg"
        case .pullRequest: "arrow.triangle.pull"
        case .cancel: "xmark"
        case .cancelCircle: "xmark.circle"
        case .chart: "chart.bar"
        case .archive: "archivebox"
        case .folderAdd: "folder.badge.plus"
        case .text: "text.alignleft"
        case .pencil: "pencil"
        case .trash: "trash"
        case .layers: "square.stack.3d.up"
        case .bell: "bell"
        case .play: "play.fill"
        case .pause: "pause.fill"
        case .arrowRight: "chevron.right"
        case .calendar: "calendar"
        case .music: "music.note"
        case .battery: "battery.75percent"
        case .headphones: "headphones"
        case .keyboard: "keyboard"
        case .mouse: "magicmouse"
        case .laptop: "laptopcomputer"
        case .sun: "sun.max"
        case .cloud: "cloud"
        case .sunCloud: "cloud.sun"
        case .rain: "cloud.rain"
        case .snow: "cloud.snow"
        case .wind: "wind"
        case .storm: "cloud.bolt.rain"
        case .moon: "moon.stars"
        case .bluetooth: "wave.3.right"
        case .phone: "iphone"
        case .earbuds: "airpodspro"
        case .earbudsCase: "airpodspro.chargingcase.wireless"
        case .bolt: "bolt.fill"
        case .drive: "externaldrive"
        case .home: "house"
        case .search: "magnifyingglass"
        case .tablet: "ipad"
        case .refresh: "arrow.clockwise"
        case .cursor: "cursorarrow.click"
        case .checkCircle: "checkmark.circle"
        }
    }
}

struct IconView: View {
    let icon: Icon
    var size: CGFloat = 16

    init(_ icon: Icon, size: CGFloat = 16) {
        self.icon = icon
        self.size = size
    }

    var body: some View {
        Image(systemName: icon.symbol)
            .font(.system(size: size * 0.92, weight: .regular))
            .frame(width: size, height: size)
    }
}

/// An icon and its word, set as one.
struct IconLabel: View {
    let title: String
    let icon: Icon

    init(_ title: String, _ icon: Icon) {
        self.title = title
        self.icon = icon
    }

    var body: some View {
        HStack(spacing: 6) {
            IconView(icon)
            Text(title)
        }
    }
}
